set -Eeuo pipefail
DB=supabase_db_thoidai-work
OPS=/opt/ops/thoidai-work
VHOST=/etc/nginx/sites-available/thoidai-work
PUBLIC_SHA=aa26878df83a3e5ba3aebb8ecdcb2e870ffa662d279231b404aa283c357e0e30
STORAGE_SHA=b13be1d8e42d56c119ddc087c15b9b91e2bf5366b95137c442fbc42d223acad6
VERIFY_SHA=77db99f89eb621c07ac7d0129747fbf03a6454d6d988a6c2d732a5b9374a42e4
status_printed=0
fail(){ printf '%s=FAIL\n' "$1"; exit 1; }
cleanup(){ rc=$?; set +e; if [ -n "${work_dir:-}" ] && [ -d "$work_dir" ]; then rm -rf -- "$work_dir"; fi; if [ "$rc" -eq 0 ] && [ "$status_printed" -eq 0 ]; then printf 'STEP_STATUS=INCOMPLETE\n'; rc=1; fi; trap - EXIT; exit "$rc"; }
trap cleanup EXIT
decode(){ payload="$1"; out="$2"; expected="$3"; label="$4"; printf '%s' "$payload" | base64 -d | gzip -d >"$out" || fail SQL_INTEGRITY; actual="$(sha256sum "$out"|awk '{print $1}')"; printf '%s_SHA256=%s\n' "$label" "$actual"; [ "$actual" = "$expected" ] || fail SQL_INTEGRITY; }
verify_counts(){ prefix="$1"; decode "$VERIFY_PAYLOAD" "$work_dir/verify.sql" "$VERIFY_SHA" SQL_VERIFY; { printf '%s\n' 'set default_transaction_read_only=on;'; cat "$work_dir/verify.sql"; } >"$work_dir/verify-readonly.sql"; while IFS='=' read -r k v; do [ -n "$k" ] && printf '%s_%s=%s\n' "$prefix" "$k" "$v"; done < <(docker exec -i "$DB" psql -U postgres -d postgres -At -F '=' <"$work_dir/verify-readonly.sql"); }
ledger_count(){ docker exec -i "$DB" psql -U postgres -d postgres -Atqc "select count(*) from supabase_migrations.schema_migrations where version like '$1%';" </dev/null; }
run_migration(){ payload="$1"; expected="$2"; role="$3"; version="$4"; name="$5"; label="$6"; decode "$payload" "$work_dir/$label.sql" "$expected" "SQL_$label"; docker exec -i "$DB" psql -U "$role" -d postgres -v ON_ERROR_STOP=1 <"$work_dir/$label.sql" || fail "MIGRATION_$label"; if [ "$(ledger_count "$version")" -eq 0 ]; then docker exec -i "$DB" psql -U supabase_admin -d postgres -v ON_ERROR_STOP=1 -v sql="$(<"$work_dir/$label.sql")" -v ver="$version" -v name="$name" <<'SQL' || fail "LEDGER_$label"
do $ledger$
begin
 if not exists (select 1 from information_schema.columns where table_schema='supabase_migrations' and table_name='schema_migrations' and column_name='statements') then raise exception 'schema_migrations.statements column missing'; end if;
end
$ledger$;
insert into supabase_migrations.schema_migrations(version,name,statements) values (:'ver', :'name', array[:'sql']) on conflict (version) do nothing;
SQL
 fi; [ "$(ledger_count "$version")" -eq 1 ] || fail "LEDGER_$label"; printf 'MIGRATION_%s=PASS\n' "$label"; }
 assert_counts(){ data="$1"; mode="$2"; for key in TABLE_LEAK FUNCTION_LEAK POLICY_LEAK DEFAULT_ACL_LEAK RLS_OFF_COUNT STORAGE_ANON_POLICY STORAGE_OBJECTS_ANON_GRANT STORAGE_PUBLIC_BUCKETS; do case "$mode:$key" in BEFORE:TABLE_LEAK) expected=9;; BEFORE:FUNCTION_LEAK) expected=13;; BEFORE:POLICY_LEAK) expected=6;; BEFORE:DEFAULT_ACL_LEAK) expected=24;; BEFORE:RLS_OFF_COUNT) expected=4;; BEFORE:STORAGE_ANON_POLICY) expected=2;; BEFORE:STORAGE_OBJECTS_ANON_GRANT) expected=2;; BEFORE:STORAGE_PUBLIC_BUCKETS) expected=1;; AFTER:STORAGE_ANON_POLICY) expected=2;; AFTER:STORAGE_OBJECTS_ANON_GRANT) expected=2;; AFTER:STORAGE_PUBLIC_BUCKETS) expected=1;; *) expected=0;; esac; value="$(printf '%s\n' "$data"|awk -F= -v k="${mode}_$key" '$1==k{print $2; exit}')"; [ "$value" = "$expected" ] || { [ "$mode" = BEFORE ] && printf 'BASELINE_MATCH=NO\n'; fail "${mode}_$key"; }; done; rpc="$(printf '%s\n' "$data"|awk -F= -v k="${mode}_SERVICE_ROLE_RPC_EXECUTE_COUNT" '$1==k{print $2; exit}')"; [ "$rpc" = 108 ] || { [ "$mode" = BEFORE ] && printf 'BASELINE_MATCH=NO\n'; fail "${mode}_SERVICE_ROLE_RPC_EXECUTE_COUNT"; }; [ "$mode" = BEFORE ] && printf 'BASELINE_MATCH=YES\n'; return 0; }
 backup_step(){ free_kib="$(df -Pk /|awk 'NR==2{print $4}')"; printf 'DISK_REQUIRED_GIB=11\n'; [ "$free_kib" -ge $((11*1024*1024)) ] || fail DISK_GATE; backup_dir="$OPS/backups/c01-pre-$timestamp"; mkdir -p "$backup_dir"; chmod 0700 "$backup_dir"; docker exec "$DB" pg_dump -U postgres -d postgres -Fc >"$backup_dir/postgres.dump"; chmod 0600 "$backup_dir/postgres.dump"; [ -s "$backup_dir/postgres.dump" ] || fail BACKUP; printf 'BACKUP_PATH=%s\nBACKUP_BYTES=%s\nBACKUP_SHA256=%s\n' "$backup_dir/postgres.dump" "$(stat -c '%s' "$backup_dir/postgres.dump")" "$(sha256sum "$backup_dir/postgres.dump"|awk '{print $1}')"; entries="$(docker exec -i "$DB" pg_restore --list <"$backup_dir/postgres.dump"|wc -l)"; printf 'BACKUP_LIST_ENTRIES=%s\n' "$entries"; [ "$entries" -gt 100 ] || fail BACKUP_LIST_ENTRIES; printf '%s\n' "$backup_dir/postgres.dump" >"$OPS/c01-last-backup"; chmod 0600 "$OPS/c01-last-backup"; before="$(verify_counts BEFORE)"; printf '%s\n' "$before"; assert_counts "$before" BEFORE; printf 'STEP_BACKUP=PASS\n'; }
 migrate_step(){ [ -s "$OPS/c01-last-backup" ] || fail BACKUP_REQUIRED; backup_path="$(cat "$OPS/c01-last-backup")"; [ -f "$backup_path" ] && [ "$(( $(date +%s)-$(stat -c %Y "$backup_path") ))" -lt 7200 ] || fail BACKUP_FRESHNESS; if [ "$(ledger_count 20261027090000)" -eq 0 ]; then run_migration "$PUBLIC_PAYLOAD" "$PUBLIC_SHA" postgres 20261027090000 anon_access_lockdown PUBLIC; else printf 'MIGRATION_PUBLIC=ALREADY_APPLIED\n'; fi; printf 'STEP_MIGRATE=PASS\n'; }
 storage_step(){ [ -s "$OPS/c01-last-backup" ] || fail BACKUP_REQUIRED; backup_path="$(cat "$OPS/c01-last-backup")"; [ -f "$backup_path" ] && [ "$(( $(date +%s)-$(stat -c %Y "$backup_path") ))" -lt 7200 ] || fail BACKUP_FRESHNESS; if [ "$(ledger_count 20261027090100)" -eq 0 ]; then run_migration "$STORAGE_PAYLOAD" "$STORAGE_SHA" supabase_admin 20261027090100 storage_anon_lockdown STORAGE; else printf 'MIGRATION_STORAGE=ALREADY_APPLIED\n'; fi; printf 'STEP_STORAGE=PASS\n'; }
 nginx_step(){ nginx_backup="$OPS/nginx-thoidai-work.pre-c01.$timestamp"; cp -- "$VHOST" "$nginx_backup"; chmod 0600 "$nginx_backup"; if grep -Fq 'allow 103.216.118.49;' "$VHOST"; then printf 'NGINX=ALREADY_APPLIED\nSTEP_NGINX=PASS\n'; return; fi; [ "$(grep -Ec '^[[:space:]]*location /supa/ \{[[:space:]]*$' "$VHOST")" -eq 1 ] || fail NGINX_LOCATION; awk '{print; if ($0 ~ /^[[:space:]]*location \/supa\/ \{[[:space:]]*$/) print "    allow 127.0.0.1;\n    allow 103.216.118.49;\n    deny all;"}' "$VHOST" >"$work_dir/nginx.new"; cp -- "$work_dir/nginx.new" "$VHOST"; for line in 'allow 127.0.0.1;' 'allow 103.216.118.49;' 'deny all;'; do [ "$(grep -Fc "$line" "$VHOST")" -eq 1 ] || { cp -- "$nginx_backup" "$VHOST"; fail NGINX; }; done; if ! nginx -t >/dev/null 2>&1 || ! nginx -T 2>/dev/null|grep -Fq 'proxy_buffer_size 16k;' || ! nginx -T 2>/dev/null|grep -Fq 'proxy_buffers 8 16k;' || ! nginx -T 2>/dev/null|grep -Fq 'proxy_busy_buffers_size 32k;'; then cp -- "$nginx_backup" "$VHOST"; printf 'NGINX=ROLLED_BACK\n'; exit 1; fi; systemctl reload nginx; printf 'NGINX=PASS\nSTEP_NGINX=PASS\n'; }
 verify_step(){ after="$(verify_counts AFTER)"; printf '%s\n' "$after"; assert_counts "$after" AFTER; missing="$(printf '%s\n' "$after"|awk -F= '$1 ~ /^AFTER_SERVICE_ROLE_MISSING_/ {if($2!=0) print $1}' )"; [ -z "$missing" ] || fail SERVICE_ROLE_MISSING; ledger="$(docker exec -i "$DB" psql -U postgres -d postgres -Atqc "select count(*) from supabase_migrations.schema_migrations where version like '2026102709%';" </dev/null)"; printf 'LEDGER_C01=%s\n' "$ledger"; [ "$ledger" -eq 1 ] || fail LEDGER_C01; [ "$(curl -fsS -o /dev/null -w '%{http_code}' http://127.0.0.1:3001/login)" = 200 ] || fail LOCAL_HEALTH; [ "$(curl -fsS -o /dev/null -w '%{http_code}' https://thoidai.online/login)" = 200 ] || fail PUBLIC_HEALTH; printf 'NGINX_SUPA_FROM_VPS=%s\n' "$(curl -ksS -o /dev/null -w '%{http_code}' https://thoidai.online/supa/rest/v1/)"; printf 'JOURNAL_PERMISSION_ERRORS=%s\n' "$(journalctl -u thoidai-work --since '-20 min'|grep -Eic 'permission denied|42501'||true)"; printf 'NRESTARTS=%s\n' "$(systemctl show thoidai-work -p NRestarts --value)"; printf 'STEP_VERIFY=PASS\n'; }
main(){ timestamp="$(date -u +%Y%m%dT%H%M%SZ)"; work_dir="$(mktemp -d /tmp/c01-apply.XXXXXX)"; mkdir -p "$OPS"; exec 9>/run/lock/thoidai-work-deploy.lock; flock -n 9 || { printf 'DEPLOY_LOCK=BUSY\n'; exit 1; }; [ "$#" -eq 2 ] || exit 2; step="$1"; [ "$2" = --approved ] || exit 2; case "$step" in backup|migrate|storage|nginx|verify) ;; *) exit 2;; esac; PUBLIC_PAYLOAD=''; STORAGE_PAYLOAD=''; VERIFY_PAYLOAD=''; case "$step" in backup) backup_step;; migrate) migrate_step;; storage) storage_step;; nginx) nginx_step;; verify) verify_step;; esac; status_printed=1; }
main "$@"; exit $?
